          // rec.perf is only set by PERF.inject inside compile(), AFTER this block: in the first round the package is derived from
          // plugin.yml (eval fourth1/third1/second1: every leftover-drop guard was skipped in round 1 and cost a model repair)
          const perfPkg = (rec.perf && rec.perf.pkg) || PERF.perfPackageOf(ws);
