614	    case "visit_location": return `go to ${o.x} ${o.y} ${o.z} in ${o.world}`;
615	    case "break_block": return `break ${o.count} ${bare(o.block).replace(/_/g, " ")}`;
616	    case "talk": return `talk (${o.menu})`;
617	    case "survive": return `survive ${o.seconds} s`;
