661	/** Compile a whole mod (any mix of item, menu and quest design files). Item-only mods: the item compiler, unchanged. */
662	export function compileMod(inputs: unknown[], ctx: CompileContext & { assets?: CompileContext["assets"] & { advancements?: string[]; /** R3 bosses: the data pack loot tables */ lootTables?: string[] } }): ModCompileResult {
663	  const kinds = inputs.map(designKind);
664	  if (kinds.every((k) => k === "item")) {
665	    const r = compileDesigns(inputs, ctx);
666	    if (!r.ok) return { ok: false, errors: r.errors, warnings: r.warnings };
667	    return { ...r, menus: [], quests: [], bosses: [], encounters: [], huds: [], deps: [], counts: { items: r.designs.length, menus: 0, quests: 0 }, gameplay: false };
668	  }
669	  const warnings: GpIssue[] = [];
670	  if (!/^[A-Za-z][A-Za-z0-9_]{1,39}$/.test(ctx.pluginName)) return { ok: false, errors: [{ path: "pluginName", code: "bad_name", message: "the plugin name must be 2-40 letters, digits or _ starting with a letter" }], warnings };
671	  const v = validateGameplay(inputs, { version: ctx.version, namespace: ctx.namespace, assets: ctx.assets, ...(ctx.limits ? { limits: ctx.limits } : {}) });
672	  for (const f of v.files) for (const w of f.warnings) warnings.push({ ...w, path: `${f.id}: ${w.path}` });
673	  if (!v.ok) return { ok: false, errors: [...v.errors.map((e) => ({ ...e, path: e.file ? `${e.file}: ${e.path}` : e.path }))], warnings };
674	  const fe = v.features as DesignFeatures;
675	  const items = [...v.items].sort((a, b) => (a.id < b.id ? -1 : 1));
676	  const { menus, quests, bosses, encounters, huds } = v;
677	  const hasBoss = bosses.length + encounters.length > 0;
678	  const hasHud = huds.length > 0;
679	  const ext = hasBoss || hasHud;
680	  // the menu/quest library: when the mod has menus or quests, and always on the classic path (no bosses / HUDs: e.g. an
681	  // items + motions mod keeps the Gameplay main class it had before bosses and HUDs existed)
682	  const needGameplay = menus.length + quests.length > 0 || !ext;
