760	  const perms = [...items.flatMap((d) => d.permissions ?? []), ...menus.flatMap((m) => m.permissions ?? []), ...quests.flatMap((q) => q.permissions ?? [])];
761	  const desc = (ctx.description ?? [items.length ? `Items: ${items.map((d) => d.name.text).join(", ")}` : "", menus.length ? `Menus: ${menus.map((m) => m.title).join(", ")}` : "", quests.length ? `Quests: ${quests.map((q) => q.title).join(", ")}` : "", bosses.length ? `Bosses: ${bosses.map((b) => b.name.text).join(", ")}` : "", encounters.length ? `Encounters: ${encounters.map((e) => e.title).join(", ")}` : "", huds.length ? "Glyph HUD" : ""].filter(Boolean).join(". ")).slice(0, 200);
